import os
import abc
import httpx
from pydantic import BaseModel, Field
from typing import Dict, Any, Type, Optional

# Load environment variables for API keys
from dotenv import load_dotenv
load_dotenv()

class Task(BaseModel):
    prompt: str
    context: str = ""

class Result(BaseModel):
    provider: str
    output: str
    cost: float = 0.0
    telemetry: Dict[str, Any] = Field(default_factory=dict)

class AgentAdapter(abc.ABC):
    """The Universal Agent Adapter Interface (The Protocol)."""

    @abc.abstractmethod
    def execute_task(self, task: Task) -> Result:
        """Executes a task and returns a structured result."""
        pass

    @property
    @abc.abstractmethod
    def provider_name(self) -> str:
        """Returns the name of the provider."""
        pass

class OpenAIAdapter(AgentAdapter):
    """Adapter for OpenAI's API."""

    def __init__(self, model: str = "gpt-3.5-turbo"):
        self.api_key: Optional[str] = os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY environment variable not set.")
        self.api_url: str = "https://api.openai.com/v1/chat/completions"
        self.model: str = model

    @property
    def provider_name(self) -> str:
        return f"openai-{self.model}"

    def execute_task(self, task: Task) -> Result:
        headers: Dict[str, str] = {"Authorization": f"Bearer {self.api_key}"}
        json_data: Dict[str, Any] = {
            "model": self.model,
            "messages": [{"role": "user", "content": task.prompt}],
            "temperature": 0.1,
        }
        with httpx.Client() as client:
            response = client.post(self.api_url, headers=headers, json=json_data, timeout=30.0)
            response.raise_for_status()
            data: Dict[str, Any] = response.json()
            output: str = data['choices'][0]['message']['content']
            # Simplified cost model for demonstration
            # See Finance/Ops directive for rigorous model
            prompt_tokens: int = data['usage'].get('prompt_tokens', 0)
            completion_tokens: int = data['usage'].get('completion_tokens', 0)
            cost: float = (prompt_tokens * 0.0000005) + (completion_tokens * 0.0000015)
            return Result(provider=self.provider_name, output=output, cost=cost, telemetry=data['usage'])

class OllamaAdapter(AgentAdapter):
    """Adapter for a local Ollama instance."""

    def __init__(self, model: str = "llama3", host: str = "http://localhost:11434"):
        self.api_url: str = f"{host}/api/generate"
        self.model: str = model

    @property
    def provider_name(self) -> str:
        return f"ollama-{self.model}"

    def execute_task(self, task: Task) -> Result:
        json_data: Dict[str, Any] = {
            "model": self.model,
            "prompt": task.prompt,
            "stream": False,
        }
        with httpx.Client() as client:
            response = client.post(self.api_url, json=json_data, timeout=120.0)
            response.raise_for_status()
            data: Dict[str, Any] = response.json()
            output: str = data['response']
            # Cost is 0 for local models, but telemetry can track performance
            telemetry: Dict[str, Any] = {
                "total_duration_ns": data.get("total_duration"),
                "eval_count": data.get("eval_count"),
            }
            return Result(provider=self.provider_name, output=output, cost=0.0, telemetry=telemetry)

class MockAdapter(AgentAdapter):
    """Mock adapter for testing without incurring costs."""

    @property
    def provider_name(self) -> str:
        return "mock-adapter"

    def execute_task(self, task: Task) -> Result:
        output: str = f"Mock response for prompt: {task.prompt[:20]}..."
        telemetry: Dict[str, Any] = {"mock": True, "length": len(task.prompt)}
        return Result(provider=self.provider_name, output=output, cost=0.0, telemetry=telemetry)
